n=22
grid=[[0]*n for _ in range(n)]
def put(r,c,v):
    assert 0<=r<n and 0<=c<n and grid[r][c] in (0,v), (r,c,grid[r][c],v)
    grid[r][c]=v
# Color 7, translated by (2,1)
for c in range(3,7): put(5,c,7); put(8,c,7)
for r in (6,7): put(r,3,7)
# Color 3, translated by (-9,-6)
for c in range(8,14): put(4,c,3)
for r in (5,6,7,8): put(r,8,3)
for r in (5,6,8): put(r,13,3)
for c in range(8,11): put(9,c,3)
# Color 4, translated by (-2,+4)
for r in (6,7,8):
    for c in range(14,17): put(r,c,4)
# Color 9, translated by (-8,+11)
for r in (10,11):
    put(r,14,9); put(r,16,9)
for c in range(13,18): put(12,c,9)
# Color 8, translated by (+12,-3)
for r in (14,15):
    put(r,13,8); put(r,17,8)
for c in range(13,18): put(16,c,8)
# shared marker coordinates: 7/3 pair, 3/4, 4/9 pair, 9/8 pair
for r,c in [(5,7),(8,7),(7,13),(9,14),(9,16),(13,13),(13,17)]: put(r,c,2)
print('\n'.join(' '.join(map(str,row)) for row in grid))

grid=[[0]*22 for _ in range(22)]
def p(r,c,v):
    assert grid[r][c] in (0,v), (r,c,grid[r][c],v)
    grid[r][c]=v
# 7 piece
for c in range(3,7): p(3,c,7); p(6,c,7)
p(4,3,7); p(5,3,7)
# 3 piece
for c in range(8,14): p(2,c,3)
for r in (3,4,6): p(r,8,3); p(r,13,3)
p(5,8,3)
for c in (8,9,10): p(7,c,3)
# central 4
for r in (8,9,10):
    for c in (10,11,12): p(r,c,4)
# 9 piece
for r in (12,13): p(r,10,9); p(r,12,9)
for c in range(9,14): p(14,c,9)
# 8 piece
for r in (16,17): p(r,9,8); p(r,13,8)
for c in range(9,14): p(18,c,8)
# shared 2 markers
for r,c in [(3,7),(6,7),(7,11),(11,10),(11,12),(15,9),(15,13)]: p(r,c,2)
print('\n'.join(' '.join(map(str,row)) for row in grid))
